class Box<T, U> {                       // two type parameters
    private T first;
    private U second;
    Box(T first, U second) { this.first = first; this.second = second; }
    T getFirst()  { return first; }
    U getSecond() { return second; }
}
public class Main {
    public static void main(String[] args) {
        Box<String, Double> priceBox = new Box<>("Laptop", 799.99);  // <> infers
        System.out.println("Item: " + priceBox.getFirst()
                         + ", Price: $" + priceBox.getSecond());
    }
}

import java.util.List;
public class Main {
    static <T> T first(List<T> list) { return list.get(0); }   // generic method
    static <T extends Number> double sum(List<T> nums) {       // bounded type
        double total = 0;
        for (T n : nums) total += n.doubleValue();  // OK: every T is a Number
        return total;
    }
    public static void main(String[] args) {
        String s = first(List.of("a", "b"));        // T inferred as String
        System.out.println(s + " " + sum(List.of(1, 2.5, 3)));
        // sum(List.of("x"));  // compile error: String is not a Number
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("Apple", "Banana", "Cherry"));
        for (int i = 0; i < list.size(); i++)       // 1. index-based
            System.out.print(list.get(i) + " ");
        for (String fruit : list)                    // 2. enhanced for
            System.out.print(fruit + " ");
        Iterator<String> it = list.iterator();       // 3. Iterator
        while (it.hasNext())
            if (it.next().equals("Banana")) it.remove();   // safe removal
        list.stream().forEach(f -> System.out.print(f + " "));  // 4. stream
    }
}

import java.util.function.BiConsumer;
interface Greeting { void sayHello(); }   // one abstract method = functional
public class Main {
    public static void main(String[] args) {
        Greeting g1 = new Greeting() {          // anonymous class
            public void sayHello() { System.out.println("Hello (anon)"); }
        };
        Greeting g2 = () -> System.out.println("Hello (lambda)");
        g1.sayHello();
        g2.sayHello();
        BiConsumer<Integer, String> two = (a, b) -> System.out.println(a + " and " + b);
        two.accept(5, "Hello");
    }
}

import java.util.*;
import java.util.stream.*;
public class Main {
    public static void main(String[] args) {
        List<String> names = Arrays.asList("Alice", "Bob", "Charlie", "David");
        List<String> result = names.stream()
            .filter(name -> name.startsWith("A"))   // intermediate
            .map(String::toUpperCase)               // intermediate
            .sorted()                               // intermediate
            .collect(Collectors.toList());          // terminal
        System.out.println(result + " " + names);   // source unchanged
    }
}

interface Printer {
    void print();                                  // abstract: must implement
    default void scan() {                          // added later, has a body
        System.out.println("Scanning document...");
    }
    static void info() { System.out.println("Printer API v2"); }
}
class OldPrinter implements Printer {   // written before scan() existed
    public void print() { System.out.println("Printing..."); }
}
public class Main {
    public static void main(String[] args) {
        Printer p = new OldPrinter();   // still compiles
        p.print();
        p.scan();                       // inherits the default
        Printer.info();                 // static: call via interface name
    }
}

public class Main {
    enum Day { MON, TUE, SAT, SUN }
    public static void main(String[] args) {
        char grade = 'A';
        int score = switch (grade) {
            case 'A' -> { System.out.println("Excellent"); yield 100; }
            case 'B', 'C' -> 75;         // multiple labels
            default -> 50;
        };                               // ; ends the statement
        Day d = Day.SAT;
        String act = switch (d) {
            case SAT, SUN -> "Relax";
            default -> "Work";
        };
        System.out.println(score + " " + act);
    }
}
